#include "devai/strategy/dev_ai_strategy/DevDirectionalOOS_F3EF2C5C.hpp"
#include <cassert>
#include <cmath>
#include <iostream>
using namespace devai::strategy::f3ef2c5c;
int main(){
 // 2026-10-23 09:15 IST; UTC epoch generated by portable fixed value.
 const std::int64_t t=1792727100; // only minute-of-day matters to this test
 const int offset=minuteIST(t);
 const auto start=t+(9*60+15-offset)*60;
 Config c{};c.allow_short=true;c.proportional_cost_per_leg=.001;
 auto px=[&](const std::string& s,std::int64_t at){assert(s=="TEST");return at==start?100.:at==start+60?98.:97.;};
 std::vector<Decision> v{{start,start,"TEST",-1,true,true},
                         {start+60,start+60,"TEST",-1,true,true},
                         {start+120,start+120,"",0,false,false}};
 const auto r=replay(c,v,px);
 assert(r.short_entries==1&&r.long_entries==0&&r.exits==1);
 assert(r.net_pnl>0&&r.total_costs>0);
 assert(std::abs(r.gross_pnl-r.total_costs-r.net_pnl)<1e-7);
 bool blocked=false;
 try {auto invalid=v;invalid[0].model_short_certified=false;(void)replay(c,invalid,px);}catch(const std::invalid_argument&){blocked=true;}
 assert(blocked);
 blocked=false;
 try {auto invalid=v;invalid[0].latest_observation_time=start+60;(void)replay(c,invalid,px);}catch(const std::invalid_argument&){blocked=true;}
 assert(blocked);
 blocked=false;
 try {validateSplit(start,start);}catch(const std::invalid_argument&){blocked=true;}
 assert(blocked);validateSplit(start,start+60);
 std::cout<<"F3E-F2C.5C PASS (SHORT OOS replay, PnL reconciliation, certification, causal split)\n";
}
